CREATE OR REPLACE FUNCTION public.guard_ngo_verification() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NOT NULL AND NOT public.has_role(auth.uid(),'super_admin') THEN IF TG_OP='INSERT' AND (NEW.status<>'pending' OR NEW.verification_notes IS NOT NULL) THEN RAISE EXCEPTION 'Only super admins can verify NGOs'; END IF; IF TG_OP='UPDATE' AND (NEW.status IS DISTINCT FROM OLD.status OR NEW.verification_notes IS DISTINCT FROM OLD.verification_notes OR NEW.owner_id IS DISTINCT FROM OLD.owner_id) THEN RAISE EXCEPTION 'Only super admins can change NGO verification'; END IF; END IF; RETURN NEW; END $$; CREATE TRIGGER acceptance_ngo_verification_guard BEFORE INSERT OR UPDATE ON public.ngos FOR EACH ROW EXECUTE FUNCTION public.guard_ngo_verification();